<script setup>
import { ref, watch, onBeforeUnmount } from 'vue';
import {useRoute} from 'vue-router';
import {watchVisibleReport} from '../../lib/cc-visible-report';
import { ccCore } from '../../api/cc-core';
import { downloadCsv } from '../../lib/cc';
const route=useRoute();
const props=defineProps({from:String,to:String,title:{type:String,default:'Lead Journey'}});const emit=defineEmits(['open']);
const data=ref(null),busy=ref(false),error=ref('');let generation=0;
async function load(){const token=++generation;busy.value=true;error.value='';data.value=null;try{const result=await ccCore('report',{from_date:props.from,to_date:props.to});if(token===generation)data.value=result;}catch(e){if(token===generation)error.value=e.message;}finally{if(token===generation)busy.value=false;}}
watchVisibleReport(()=>[props.from,props.to],()=>route.meta.reportTab==='journey',load,()=>!!data.value&&!error.value);onBeforeUnmount(()=>generation++);
function exportAgents(){downloadCsv('cc-lead-journey.csv',[{key:'name',label:'Agent'},...['leads','contacted','booked','visited','joined','paid','unreach3','overdue'].map(key=>({key,label:key}))],data.value.agents);}
</script>
<template><section class="card"><header class="card-hdr">{{title}} <button class="btn btn-gy btn-sm" :disabled="busy" @click="load">Refresh</button><button class="btn btn-gy btn-sm" :disabled="!data||data.capped" @click="exportAgents">Export</button></header><div class="card-body"><p v-if="busy" role="status">Loading lead journey report…</p><p v-if="error" role="alert" class="cc-error">{{error}}</p><template v-if="data"><p v-if="data.capped" class="cc-error">This range reached the report limit. Choose a shorter range.</p><div class="cc-report-metrics"><div v-for="(value,key) in data.funnel" :key="key"><strong>{{key==='paid'?'₹':''}}{{Number(value).toLocaleString('en-IN')}}</strong><span>{{key.replaceAll('_',' ')}}</span></div></div><div class="tbl-wrap"><table><thead><tr><th>Agent</th><th>Leads</th><th>Contacted</th><th>Appointments</th><th>Visited</th><th>Joined</th><th>Paid</th><th>Unreachable 3+</th><th>Overdue</th></tr></thead><tbody><tr v-for="a in data.agents" :key="a.agent"><td>{{a.name}}</td><td>{{a.leads}}</td><td>{{a.contacted}}</td><td>{{a.booked}}</td><td>{{a.visited}}</td><td>{{a.joined}}</td><td>₹{{a.paid.toLocaleString('en-IN')}}</td><td>{{a.unreach3}}</td><td>{{a.overdue}}</td></tr></tbody></table></div><details><summary>Last call results</summary><p v-for="(count,result) in data.last_call_mix" :key="result">{{result}}: {{count}}</p></details><details><summary>Joined clients and conversion credit</summary><div class="tbl-wrap"><table><thead><tr><th>Lead</th><th>Owner</th><th>Joined</th><th>Paid</th><th>Credit</th></tr></thead><tbody><tr v-for="row in data.joined" :key="row.lead"><td><button class="btn btn-gy btn-sm" @click="emit('open',row.lead)">{{row.lead}}</button></td><td>{{row.owner}}</td><td>{{row.joined_on}}</td><td>₹{{row.paid}}</td><td>{{row.credit_name}}</td></tr></tbody></table></div></details><details><summary>Lead moves and verification history</summary><p v-for="(row,i) in data.moves" :key="i">{{row.event_time}} · {{row.lead}} · {{row.action}} · {{row.old_status}} → {{row.new_status}} · {{row.erp_user}}</p></details></template></div></section></template>
<style scoped>details{padding:12px 0}</style>
